64	
65	HttpRequestCommand::HttpRequestCommand(
66	    cuid_t cuid, const std::shared_ptr<Request>& req,
67	    const std::shared_ptr<FileEntry>& fileEntry, RequestGroup* requestGroup,
68	    const std::shared_ptr<HttpConnection>& httpConnection, DownloadEngine* e,
69	    const std::shared_ptr<SocketCore>& s)
70	    : AbstractCommand(cuid, req, fileEntry, requestGroup, e, s,
71	                      httpConnection->getSocketRecvBuffer()),
72	      httpConnection_(httpConnection)
73	{
74	  setTimeout(std::chrono::seconds(getOption()->getAsInt(PREF_CONNECT_TIMEOUT)));
75	  disableReadCheckSocket();
76	  setWriteCheckSocket(getSocket());
77	}
78	
79	HttpRequestCommand::~HttpRequestCommand() = default;
80	
81	namespace {
82	std::unique_ptr<HttpRequest>
83	createHttpRequest(const std::shared_ptr<Request>& req,
84	                  const std::shared_ptr<FileEntry>& fileEntry,
85	                  const std::shared_ptr<Segment>& segment,
86	                  const std::shared_ptr<Option>& option, const RequestGroup* rg,
87	                  const DownloadEngine* e,
88	                  const std::shared_ptr<Request>& proxyRequest,
89	                  int64_t endOffset = 0)
90	{
91	  auto httpRequest = make_unique<HttpRequest>();
92	  httpRequest->setUserAgent(option->get(PREF_USER_AGENT));
93	  httpRequest->setRequest(req);
94	  httpRequest->setFileEntry(fileEntry);
95	  httpRequest->setSegment(segment);
96	  httpRequest->addHeader(option->get(PREF_HEADER));
97	  httpRequest->setCookieStorage(e->getCookieStorage().get());
98	  httpRequest->setAuthConfigFactory(e->getAuthConfigFactory().get());
99	  httpRequest->setOption(option.get());
100	  httpRequest->setProxyRequest(proxyRequest);
101	  httpRequest->setAcceptMetalink(rg->getDownloadContext()->getAcceptMetalink());
102	  httpRequest->setNoWantDigest(option->getAsBool(PREF_NO_WANT_DIGEST_HEADER));
103	
104	  if (option->getAsBool(PREF_HTTP_ACCEPT_GZIP)) {
105	    httpRequest->enableAcceptGZip();
106	  }
107	  else {
108	    httpRequest->disableAcceptGZip();
109	  }
110	  if (option->getAsBool(PREF_HTTP_NO_CACHE)) {
111	    httpRequest->enableNoCache();
112	  }
113	  else {
114	    httpRequest->disableNoCache();
115	  }
116	  if (endOffset > 0) {
117	    httpRequest->setEndOffsetOverride(endOffset);
118	  }
119	  return httpRequest;
120	}
121	} // namespace
122	
123	bool HttpRequestCommand::executeInternal()
124	{
125	  // socket->setBlockingMode();
126	  if (httpConnection_->sendBufferIsEmpty()) {
127	#ifdef ENABLE_SSL
128	    if (getRequest()->getProtocol() == "https") {
129	      if (!getSocket()->tlsConnect(getRequest()->getHost())) {
130	        setReadCheckSocketIf(getSocket(), getSocket()->wantRead());
131	        setWriteCheckSocketIf(getSocket(), getSocket()->wantWrite());
132	        addCommandSelf();
133	        return false;
134	      }
135	    }
136	#endif // ENABLE_SSL
137	    if (getSegments().empty()) {
138	      auto httpRequest = createHttpRequest(
139	          getRequest(), getFileEntry(), std::shared_ptr<Segment>(), getOption(),
140	          getRequestGroup(), getDownloadEngine(), proxyRequest_);
141	      if (getOption()->getAsBool(PREF_CONDITIONAL_GET) &&
142	          (getRequest()->getProtocol() == "http" ||
143	           getRequest()->getProtocol() == "https")) {
144	
145	        std::string path;
146	
147	        if (getFileEntry()->getPath().empty()) {
148	          auto& file = getRequest()->getFile();
149	
150	          // If filename part of URI is empty, we just use
151	          // Request::DEFAULT_FILE, since it is the name we use to
152	          // store file in disk.
153	
154	          path = util::createSafePath(
155	              getOption()->get(PREF_DIR),
156	              (getRequest()->getFile().empty()
157	                   ? Request::DEFAULT_FILE
158	                   : util::percentDecode(std::begin(file), std::end(file))));
159	        }
160	        else {
161	          path = getFileEntry()->getPath();
162	        }
163	
164	        File ctrlfile(path + DefaultBtProgressInfoFile::getSuffix());
165	        File file(path);
166	
167	        if (!ctrlfile.exists() && file.exists()) {
168	          httpRequest->setIfModifiedSinceHeader(
169	              file.getModifiedTime().toHTTPDate());
170	        }
171	      }
172	      httpConnection_->sendRequest(std::move(httpRequest));
173	    }
174	    else {
175	      for (auto& segment : getSegments()) {
176	        if (!httpConnection_->isIssued(segment)) {
177	          int64_t endOffset = 0;
178	          // FTP via HTTP proxy does not support end byte marker
179	          if (getRequest()->getProtocol() != "ftp" &&
180	              getRequestGroup()->getTotalLength() > 0 && getPieceStorage()) {
181	            size_t nextIndex =
182	                getPieceStorage()->getNextUsedIndex(segment->getIndex());
183	            endOffset =
184	                std::min(getFileEntry()->getLength(),
185	                         getFileEntry()->gtoloff(
186	                             static_cast<int64_t>(segment->getSegmentLength()) *
187	                             nextIndex));
188	          }
189	          httpConnection_->sendRequest(
190	              createHttpRequest(getRequest(), getFileEntry(), segment,
191	                                getOption(), getRequestGroup(),
192	                                getDownloadEngine(), proxyRequest_, endOffset));
193	        }
194	      }
195	    }
196	  }
197	  else {
198	    httpConnection_->sendPendingData();
199	  }
200	  if (httpConnection_->sendBufferIsEmpty()) {
201	    getDownloadEngine()->addCommand(make_unique<HttpResponseCommand>(
202	        getCuid(), getRequest(), getFileEntry(), getRequestGroup(),
203	        httpConnection_, getDownloadEngine(), getSocket()));
204	    return true;
205	  }
206	  else {
207	    setReadCheckSocketIf(getSocket(), getSocket()->wantRead());
208	    setWriteCheckSocketIf(getSocket(), getSocket()->wantWrite());
209	    addCommandSelf();
210	    return false;
211	  }
212	}
