71	std::unique_ptr<Command> HttpInitiateConnectionCommand::createNextCommand(
72	    const std::string& hostname, const std::string& addr, uint16_t port,
73	    const std::vector<std::string>& resolvedAddresses,
74	    const std::shared_ptr<Request>& proxyRequest)
75	{
76	  if (proxyRequest) {
77	    std::shared_ptr<SocketCore> pooledSocket =
78	        getDownloadEngine()->popPooledSocket(
79	            getRequest()->getHost(), getRequest()->getPort(),
80	            proxyRequest->getHost(), proxyRequest->getPort());
81	    std::string proxyMethod = resolveProxyMethod(getRequest()->getProtocol());
82	    if (!pooledSocket) {
83	      A2_LOG_INFO(fmt(MSG_CONNECTING_TO_SERVER, getCuid(), addr.c_str(), port));
84	      createSocket();
85	      getSocket()->establishConnection(addr, port);
86	
87	      getRequest()->setConnectedAddrInfo(hostname, addr, port);
88	      auto c = make_unique<ConnectCommand>(
89	          getCuid(), getRequest(), proxyRequest, getFileEntry(),
90	          getRequestGroup(), getDownloadEngine(), getSocket());
91	      if (proxyMethod == V_TUNNEL) {
92	        c->setControlChain(std::make_shared<HttpProxyRequestConnectChain>());
93	      }
94	      else if (proxyMethod == V_GET) {
95	        c->setControlChain(std::make_shared<HttpRequestConnectChain>());
96	      }
97	      else {
98	        // Unreachable
99	        assert(0);
100	      }
101	      setupBackupConnection(hostname, addr, port, c.get());
102	      return std::move(c);
103	    }
104	    else {
105	      setConnectedAddrInfo(getRequest(), hostname, pooledSocket);
106	      auto c = make_unique<HttpRequestCommand>(
107	          getCuid(), getRequest(), getFileEntry(), getRequestGroup(),
108	          std::make_shared<HttpConnection>(
109	              getCuid(), pooledSocket,
110	              std::make_shared<SocketRecvBuffer>(pooledSocket)),
111	          getDownloadEngine(), pooledSocket);
112	      if (proxyMethod == V_GET) {
113	        c->setProxyRequest(proxyRequest);
114	      }
115	      return std::move(c);
116	    }
117	  }
118	  else {
119	    std::shared_ptr<SocketCore> pooledSocket =
120	        getDownloadEngine()->popPooledSocket(resolvedAddresses,
121	                                             getRequest()->getPort());
122	    if (!pooledSocket) {
123	      A2_LOG_INFO(fmt(MSG_CONNECTING_TO_SERVER, getCuid(), addr.c_str(), port));
124	      createSocket();
125	      getSocket()->establishConnection(addr, port);
126	
127	      getRequest()->setConnectedAddrInfo(hostname, addr, port);
128	      auto c = make_unique<ConnectCommand>(getCuid(), getRequest(),
129	                                           proxyRequest, // must be null
130	                                           getFileEntry(), getRequestGroup(),
131	                                           getDownloadEngine(), getSocket());
132	      c->setControlChain(std::make_shared<HttpRequestConnectChain>());
133	      setupBackupConnection(hostname, addr, port, c.get());
134	      return std::move(c);
135	    }
136	    else {
137	      setSocket(pooledSocket);
138	      setConnectedAddrInfo(getRequest(), hostname, pooledSocket);
139	
140	      return make_unique<HttpRequestCommand>(
141	          getCuid(), getRequest(), getFileEntry(), getRequestGroup(),
142	          std::make_shared<HttpConnection>(
143	              getCuid(), getSocket(),
144	              std::make_shared<SocketRecvBuffer>(getSocket())),
145	          getDownloadEngine(), getSocket());
146	    }
147	  }
148	}
