144	bool HttpResponseCommand::executeInternal()
145	{
146	  auto httpResponse = httpConnection_->receiveResponse();
147	  if (!httpResponse) {
148	    // The server has not responded to our request yet.
149	    // For socket->wantRead() == true, setReadCheckSocket(socket) is already
150	    // done in the constructor.
151	    setWriteCheckSocketIf(getSocket(), getSocket()->wantWrite());
152	    addCommandSelf();
153	    return false;
154	  }
155	
156	  // check HTTP status code
157	  httpResponse->validateResponse();
158	  httpResponse->retrieveCookie();
159	
160	  const auto& httpHeader = httpResponse->getHttpHeader();
161	  // Disable persistent connection if:
162	  //   Connection: close is received or the remote server is not HTTP/1.1.
163	  // We don't care whether non-HTTP/1.1 server returns Connection: keep-alive.
164	  auto& req = getRequest();
165	  req->supportsPersistentConnection(
166	      httpResponse->supportsPersistentConnection());
167	  if (req->isPipeliningEnabled()) {
168	    req->setMaxPipelinedRequest(
169	        getOption()->getAsInt(PREF_MAX_HTTP_PIPELINING));
170	  }
171	  else {
172	    req->setMaxPipelinedRequest(1);
173	  }
174	
175	  auto statusCode = httpResponse->getStatusCode();
176	  auto& ctx = getDownloadContext();
177	  auto grp = getRequestGroup();
178	  auto& fe = getFileEntry();
179	
180	  if (statusCode == 304) {
181	    int64_t totalLength = httpResponse->getEntityLength();
182	    fe->setLength(totalLength);
183	    grp->initPieceStorage();
184	    getPieceStorage()->markAllPiecesDone();
185	    // Just set checksum verification done.
186	    ctx->setChecksumVerified(true);
187	
188	    if (fe->getPath().empty()) {
189	      // If path is empty, set default file name or file portion of
190	      // URI.  This is the file we used to get modified date.
191	      auto& file = getRequest()->getFile();
192	      auto suffixPath = util::createSafePath(
193	          getRequest()->getFile().empty()
194	              ? Request::DEFAULT_FILE
195	              : util::percentDecode(std::begin(file), std::end(file)));
196	      fe->setPath(util::applyDir(getOption()->get(PREF_DIR), suffixPath));
197	      fe->setSuffixPath(suffixPath);
198	    }
199	
200	    A2_LOG_NOTICE(fmt(MSG_DOWNLOAD_ALREADY_COMPLETED,
201	                      GroupId::toHex(grp->getGID()).c_str(),
202	                      grp->getFirstFilePath().c_str()));
203	    poolConnection();
204	    fe->poolRequest(req);
205	    return true;
206	  }
207	
208	  if (!getPieceStorage()) {
209	    // Metalink/HTTP
210	    if (ctx->getAcceptMetalink()) {
211	      if (httpHeader->defined(HttpHeader::LINK)) {
212	        ctx->setAcceptMetalink(false);
213	        std::vector<MetalinkHttpEntry> entries;
214	        httpResponse->getMetalinKHttpEntries(entries, getOption());
215	        for (const auto& e : entries) {
216	          fe->addUri(e.uri);
217	          A2_LOG_DEBUG(fmt("Adding URI=%s", e.uri.c_str()));
218	        }
219	      }
220	    }
221	
222	    if (httpHeader->defined(HttpHeader::DIGEST)) {
223	      std::vector<Checksum> checksums;
224	      httpResponse->getDigest(checksums);
225	      for (const auto& checksum : checksums) {
226	        if (ctx->getHashType().empty()) {
227	          A2_LOG_DEBUG(fmt("Setting digest: type=%s, digest=%s",
228	                           checksum.getHashType().c_str(),
229	                           checksum.getDigest().c_str()));
230	          ctx->setDigest(checksum.getHashType(), checksum.getDigest());
231	          break;
232	        }
233	
234	        if (checkChecksum(ctx, checksum)) {
235	          break;
236	        }
237	      }
238	    }
239	  }
240	
241	  if (statusCode >= 300) {
242	    if (statusCode == 404) {
243	      grp->increaseAndValidateFileNotFoundCount();
244	    }
245	    return skipResponseBody(std::move(httpResponse));
246	  }
247	
248	  if (fe->isUniqueProtocol()) {
249	    // Redirection should be considered here. We need to parse
250	    // original URI to get hostname.
251	    const std::string& uri = getRequest()->getUri();
252	    uri_split_result us;
253	    if (uri_split(&us, uri.c_str()) == 0) {
254	      std::string host = uri::getFieldString(us, USR_HOST, uri.c_str());
255	      fe->removeURIWhoseHostnameIs(host);
256	    }
257	  }
258	
259	  if (!getPieceStorage()) {
260	    ctx->setAcceptMetalink(false);
261	    int64_t totalLength = httpResponse->getEntityLength();
262	    fe->setLength(totalLength);
263	    if (fe->getPath().empty()) {
264	      auto suffixPath = util::createSafePath(httpResponse->determineFilename(
265	          getOption()->getAsBool(PREF_CONTENT_DISPOSITION_DEFAULT_UTF8)));
266	      fe->setPath(util::applyDir(getOption()->get(PREF_DIR), suffixPath));
267	      fe->setSuffixPath(suffixPath);
268	    }
269	    fe->setContentType(httpResponse->getContentType());
270	    grp->preDownloadProcessing();
271	
272	    // update last modified time
273	    updateLastModifiedTime(httpResponse->getLastModifiedTime());
274	
275	    // If both transfer-encoding and total length is specified, we
276	    // should have ignored total length.  In this case, we can not do
277	    // segmented downloading
278	    if (totalLength == 0 || shouldInflateContentEncoding(httpResponse.get())) {
279	      // we ignore content-length when inflate is required
280	      fe->setLength(0);
281	      if (req->getMethod() == Request::METHOD_GET &&
282	          (totalLength != 0 || !httpResponse->getHttpHeader()->defined(
283	                                   HttpHeader::CONTENT_LENGTH))) {
284	        // DownloadContext::knowsTotalLength() == true only when
285	        // server says the size of file is 0 explicitly.
286	        getDownloadContext()->markTotalLengthIsUnknown();
287	      }
288	      return handleOtherEncoding(std::move(httpResponse));
289	    }
290	
291	    return handleDefaultEncoding(std::move(httpResponse));
292	  }
293	
294	  if (!ctx->getHashType().empty() && httpHeader->defined(HttpHeader::DIGEST)) {
295	    std::vector<Checksum> checksums;
296	    httpResponse->getDigest(checksums);
297	    for (const auto& checksum : checksums) {
298	      if (checkChecksum(ctx, checksum)) {
299	        break;
300	      }
301	    }
302	  }
303	
304	  // validate totalsize
305	  grp->validateTotalLength(fe->getLength(), httpResponse->getEntityLength());
306	  // update last modified time
307	  updateLastModifiedTime(httpResponse->getLastModifiedTime());
308	
309	  if (grp->getTotalLength() == 0) {
310	    // Since total length is unknown, the file size in previously
311	    // failed download could be larger than the size this time.
312	    // Also we can't resume in this case too.  So truncate the file
313	    // anyway.
314	    getPieceStorage()->getDiskAdaptor()->truncate(0);
315	    auto teFilter = getTransferEncodingStreamFilter(
316	        httpResponse.get(), getContentEncodingStreamFilter(httpResponse.get()));
317	    getDownloadEngine()->addCommand(createHttpDownloadCommand(
318	        std::move(httpResponse), std::move(teFilter)));
319	  }
320	  else {
321	    auto teFilter = getTransferEncodingStreamFilter(httpResponse.get());
322	    getDownloadEngine()->addCommand(createHttpDownloadCommand(
323	        std::move(httpResponse), std::move(teFilter)));
324	  }
325	
326	  return true;
327	}
328	
329	void HttpResponseCommand::updateLastModifiedTime(const Time& lastModified)
330	{
331	  if (getOption()->getAsBool(PREF_REMOTE_TIME)) {
332	    getRequestGroup()->updateLastModifiedTime(lastModified);
333	  }
334	}
335	
336	bool HttpResponseCommand::shouldInflateContentEncoding(
337	    HttpResponse* httpResponse)
338	{
339	  // Basically, on the fly inflation cannot be made with segment
340	  // download, because in each segment we don't know where the date
341	  // should be written.  So turn off segmented downloading.
342	  // Meanwhile, Some server returns content-encoding: gzip for .tgz
343	  // files.  I think those files should not be inflated by clients,
344	  // because it is the original format of those files. Current
345	  // implementation just inflates these files nonetheless.
346	  const std::string& ce = httpResponse->getContentEncoding();
347	  return httpResponse->getHttpRequest()->acceptGZip() &&
348	         (ce == "gzip" || ce == "deflate");
349	}
350	
351	bool HttpResponseCommand::handleDefaultEncoding(
352	    std::unique_ptr<HttpResponse> httpResponse)
353	{
354	  auto progressInfoFile = std::make_shared<DefaultBtProgressInfoFile>(
355	      getDownloadContext(), std::shared_ptr<PieceStorage>{}, getOption().get());
356	  getRequestGroup()->adjustFilename(progressInfoFile);
357	  getRequestGroup()->initPieceStorage();
358	
359	  if (getOption()->getAsBool(PREF_DRY_RUN)) {
360	    onDryRunFileFound();
361	    return true;
362	  }
363	
364	  auto checkEntry = getRequestGroup()->createCheckIntegrityEntry();
365	  if (!checkEntry) {
366	    return true;
367	  }
368	
369	  File file(getRequestGroup()->getFirstFilePath());
370	  // We have to make sure that command that has Request object must
371	  // have segment after PieceStorage is initialized. See
372	  // AbstractCommand::execute()
373	  auto segment = getSegmentMan()->getSegmentWithIndex(getCuid(), 0);
374	  // pipelining requires implicit range specified. But the request for
375	  // this response most likely doesn't contains range header. This means
376	  // we can't continue to use this socket because server sends all entity
377	  // body instead of a segment.
378	  // Therefore, we shutdown the socket here if pipelining is enabled.
379	  if (getRequest()->getMethod() == Request::METHOD_GET && segment &&
380	      segment->getPositionToWrite() == 0 &&
381	      !getRequest()->isPipeliningEnabled()) {
382	    auto teFilter = getTransferEncodingStreamFilter(httpResponse.get());
383	    checkEntry->pushNextCommand(createHttpDownloadCommand(
384	        std::move(httpResponse), std::move(teFilter)));
385	  }
386	  else {
387	    getSegmentMan()->cancelSegment(getCuid());
388	    getFileEntry()->poolRequest(getRequest());
389	  }
390	
391	  prepareForNextAction(std::move(checkEntry));
392	
393	  if (getRequest()->getMethod() == Request::METHOD_HEAD) {
394	    poolConnection();
395	    getRequest()->setMethod(Request::METHOD_GET);
396	  }
397	
398	  return true;
399	}
400	
401	bool HttpResponseCommand::handleOtherEncoding(
402	    std::unique_ptr<HttpResponse> httpResponse)
403	{
404	  // We assume that RequestGroup::getTotalLength() == 0 here
405	  if (getOption()->getAsBool(PREF_DRY_RUN)) {
406	    getRequestGroup()->initPieceStorage();
407	    onDryRunFileFound();
408	    return true;
409	  }
410	
411	  if (getRequest()->getMethod() == Request::METHOD_HEAD) {
412	    poolConnection();
413	    getRequest()->setMethod(Request::METHOD_GET);
414	    return prepareForRetry(0);
415	  }
416	
417	  // In this context, knowsTotalLength() is true only when the file is
418	  // really zero-length.
419	
420	  auto streamFilter = getTransferEncodingStreamFilter(
421	      httpResponse.get(), getContentEncodingStreamFilter(httpResponse.get()));
422	  // If chunked transfer-encoding is specified, we have to read end of
423	  // chunk markers(0\r\n\r\n, for example).
424	  bool chunkedUsed = streamFilter && streamFilter->getName() ==
425	                                         ChunkedDecodingStreamFilter::NAME;
426	
427	  // For zero-length file, check existing file comparing its size
428	  if (!chunkedUsed && getDownloadContext()->knowsTotalLength() &&
429	      getRequestGroup()->downloadFinishedByFileLength()) {
430	    getRequestGroup()->initPieceStorage();
431	
432	    // TODO Known issue: if .aria2 file exists, it will not be deleted
433	    // on successful verification, because .aria2 file is not loaded.
434	    // See also FtpNegotiationCommand::onFileSizeDetermined()
435	    if (getDownloadContext()->isChecksumVerificationNeeded()) {
436	      A2_LOG_DEBUG("Zero length file exists. Verify checksum.");
437	      auto entry = make_unique<ChecksumCheckIntegrityEntry>(getRequestGroup());
438	      entry->initValidator();
439	      getPieceStorage()->getDiskAdaptor()->openExistingFile();
440	      getDownloadEngine()->getCheckIntegrityMan()->pushEntry(std::move(entry));
441	    }
442	    else {
443	      getPieceStorage()->markAllPiecesDone();
444	      getDownloadContext()->setChecksumVerified(true);
445	      A2_LOG_NOTICE(fmt(MSG_DOWNLOAD_ALREADY_COMPLETED,
446	                        GroupId::toHex(getRequestGroup()->getGID()).c_str(),
447	                        getRequestGroup()->getFirstFilePath().c_str()));
448	    }
449	    poolConnection();
450	    return true;
451	  }
452	
453	  getRequestGroup()->adjustFilename(std::make_shared<NullProgressInfoFile>());
454	  getRequestGroup()->initPieceStorage();
455	  getPieceStorage()->getDiskAdaptor()->initAndOpenFile();
456	
457	  // Local file size becomes zero when DiskAdaptor::initAndOpenFile()
458	  // is called. So zero-length file is complete if chunked encoding is
459	  // not used.
460	  if (!chunkedUsed && getDownloadContext()->knowsTotalLength()) {
461	    A2_LOG_DEBUG("File length becomes zero and it means download completed.");
462	    // TODO Known issue: if .aria2 file exists, it will not be deleted
463	    // on successful verification, because .aria2 file is not loaded.
464	    // See also FtpNegotiationCommand::onFileSizeDetermined()
465	    if (getDownloadContext()->isChecksumVerificationNeeded()) {
466	      A2_LOG_DEBUG("Verify checksum for zero-length file");
467	      auto entry = make_unique<ChecksumCheckIntegrityEntry>(getRequestGroup());
468	      entry->initValidator();
469	      getDownloadEngine()->getCheckIntegrityMan()->pushEntry(std::move(entry));
470	    }
471	    else {
472	      getRequestGroup()->getPieceStorage()->markAllPiecesDone();
473	    }
474	    poolConnection();
475	    return true;
476	  }
477	
478	  // We have to make sure that command that has Request object must
479	  // have segment after PieceStorage is initialized. See
480	  // AbstractCommand::execute()
481	  getSegmentMan()->getSegmentWithIndex(getCuid(), 0);
482	
483	  getDownloadEngine()->addCommand(createHttpDownloadCommand(
484	      std::move(httpResponse), std::move(streamFilter)));
485	  return true;
486	}
487	
488	bool HttpResponseCommand::skipResponseBody(
489	    std::unique_ptr<HttpResponse> httpResponse)
490	{
491	  auto filter = getTransferEncodingStreamFilter(httpResponse.get());
492	  // We don't use Content-Encoding here because this response body is just
493	  // thrown away.
494	  auto httpResponsePtr = httpResponse.get();
495	  auto command = make_unique<HttpSkipResponseCommand>(
496	      getCuid(), getRequest(), getFileEntry(), getRequestGroup(),
497	      httpConnection_, std::move(httpResponse), getDownloadEngine(),
498	      getSocket());
499	  command->installStreamFilter(std::move(filter));
500	
501	  // If request method is HEAD or the response body is zero-length,
502	  // set command's status to real time so that avoid read check blocking
503	  if (getRequest()->getMethod() == Request::METHOD_HEAD ||
504	      (httpResponsePtr->getEntityLength() == 0 &&
505	       !httpResponsePtr->isTransferEncodingSpecified())) {
506	    command->setStatusRealtime();
507	    // If entity length == 0, then socket read/write check must be disabled.
508	    command->disableSocketCheck();
509	    getDownloadEngine()->setNoWait(true);
510	  }
511	
512	  getDownloadEngine()->addCommand(std::move(command));
513	  return true;
514	}
515	
516	namespace {
517	
518	bool decideFileAllocation(StreamFilter* filter)
519	{
520	#ifdef HAVE_ZLIB
521	  for (StreamFilter* f = filter; f; f = f->getDelegate().get()) {
522	    // Since the compressed file's length are returned in the response header
523	    // and the decompressed file size is unknown at this point, disable file
524	    // allocation here.
525	    if (f->getName() == GZipDecodingStreamFilter::NAME) {
526	      return false;
527	    }
528	  }
529	#endif // HAVE_ZLIB
530	
531	  return true;
532	}
533	
534	} // namespace
535	
536	std::unique_ptr<HttpDownloadCommand>
537	HttpResponseCommand::createHttpDownloadCommand(
538	    std::unique_ptr<HttpResponse> httpResponse,
539	    std::unique_ptr<StreamFilter> filter)
540	{
541	
542	  auto command = make_unique<HttpDownloadCommand>(
543	      getCuid(), getRequest(), getFileEntry(), getRequestGroup(),
544	      std::move(httpResponse), httpConnection_, getDownloadEngine(),
545	      getSocket());
546	  command->setStartupIdleTime(
547	      std::chrono::seconds(getOption()->getAsInt(PREF_STARTUP_IDLE_TIME)));
548	  command->setLowestDownloadSpeedLimit(
549	      getOption()->getAsInt(PREF_LOWEST_SPEED_LIMIT));
550	  if (getRequestGroup()->isFileAllocationEnabled() &&
551	      !decideFileAllocation(filter.get())) {
552	    getRequestGroup()->setFileAllocationEnabled(false);
553	  }
554	  command->installStreamFilter(std::move(filter));
555	  getRequestGroup()->getURISelector()->tuneDownloadCommand(
556	      getFileEntry()->getRemainingUris(), command.get());
557	
558	  return command;
559	}
560	
561	void HttpResponseCommand::poolConnection()
562	{
563	  if (getRequest()->supportsPersistentConnection()) {
564	    getDownloadEngine()->poolSocket(getRequest(), createProxyRequest(),
565	                                    getSocket());
566	  }
567	}
568	
569	void HttpResponseCommand::onDryRunFileFound()
570	{
571	  getPieceStorage()->markAllPiecesDone();
572	  getDownloadContext()->setChecksumVerified(true);
573	  poolConnection();
574	}
575	
576	bool HttpResponseCommand::checkChecksum(
577	    const std::shared_ptr<DownloadContext>& dctx, const Checksum& checksum)
578	{
579	  if (dctx->getHashType() == checksum.getHashType()) {
580	    if (dctx->getDigest() != checksum.getDigest()) {
581	      throw DL_ABORT_EX("Invalid hash found in Digest header field.");
582	    }
583	    A2_LOG_INFO("Valid hash found in Digest header field.");
584	    return true;
585	  }
586	
587	  return false;
588	}
589	
590	} // namespace aria2
