144	bool HttpResponseCommand::executeInternal()
145	{
146	  auto httpResponse = httpConnection_->receiveResponse();
147	  if (!httpResponse) {
148	    // The server has not responded to our request yet.
149	    // For socket->wantRead() == true, setReadCheckSocket(socket) is already
150	    // done in the constructor.
151	    setWriteCheckSocketIf(getSocket(), getSocket()->wantWrite());
152	    addCommandSelf();
153	    return false;
154	  }
155	
156	  // check HTTP status code
157	  httpResponse->validateResponse();
158	  httpResponse->retrieveCookie();
159	
160	  const auto& httpHeader = httpResponse->getHttpHeader();
161	  // Disable persistent connection if:
162	  //   Connection: close is received or the remote server is not HTTP/1.1.
163	  // We don't care whether non-HTTP/1.1 server returns Connection: keep-alive.
164	  auto& req = getRequest();
165	  req->supportsPersistentConnection(
166	      httpResponse->supportsPersistentConnection());
167	  if (req->isPipeliningEnabled()) {
168	    req->setMaxPipelinedRequest(
169	        getOption()->getAsInt(PREF_MAX_HTTP_PIPELINING));
170	  }
171	  else {
172	    req->setMaxPipelinedRequest(1);
173	  }
174	
175	  auto statusCode = httpResponse->getStatusCode();
176	  auto& ctx = getDownloadContext();
177	  auto grp = getRequestGroup();
178	  auto& fe = getFileEntry();
179	
180	  if (statusCode == 304) {
181	    int64_t totalLength = httpResponse->getEntityLength();
182	    fe->setLength(totalLength);
183	    grp->initPieceStorage();
184	    getPieceStorage()->markAllPiecesDone();
185	    // Just set checksum verification done.
186	    ctx->setChecksumVerified(true);
187	
188	    if (fe->getPath().empty()) {
189	      // If path is empty, set default file name or file portion of
190	      // URI.  This is the file we used to get modified date.
191	      auto& file = getRequest()->getFile();
192	      auto suffixPath = util::createSafePath(
193	          getRequest()->getFile().empty()
194	              ? Request::DEFAULT_FILE
195	              : util::percentDecode(std::begin(file), std::end(file)));
196	      fe->setPath(util::applyDir(getOption()->get(PREF_DIR), suffixPath));
197	      fe->setSuffixPath(suffixPath);
198	    }
199	
200	    A2_LOG_NOTICE(fmt(MSG_DOWNLOAD_ALREADY_COMPLETED,
201	                      GroupId::toHex(grp->getGID()).c_str(),
202	                      grp->getFirstFilePath().c_str()));
203	    poolConnection();
204	    fe->poolRequest(req);
205	    return true;
206	  }
207	
208	  if (!getPieceStorage()) {
209	    // Metalink/HTTP
210	    if (ctx->getAcceptMetalink()) {
211	      if (httpHeader->defined(HttpHeader::LINK)) {
212	        ctx->setAcceptMetalink(false);
213	        std::vector<MetalinkHttpEntry> entries;
214	        httpResponse->getMetalinKHttpEntries(entries, getOption());
215	        for (const auto& e : entries) {
216	          fe->addUri(e.uri);
217	          A2_LOG_DEBUG(fmt("Adding URI=%s", e.uri.c_str()));
218	        }
219	      }
220	    }
221	
222	    if (httpHeader->defined(HttpHeader::DIGEST)) {
223	      std::vector<Checksum> checksums;
224	      httpResponse->getDigest(checksums);
225	      for (const auto& checksum : checksums) {
226	        if (ctx->getHashType().empty()) {
227	          A2_LOG_DEBUG(fmt("Setting digest: type=%s, digest=%s",
228	                           checksum.getHashType().c_str(),
229	                           checksum.getDigest().c_str()));
230	          ctx->setDigest(checksum.getHashType(), checksum.getDigest());
231	          break;
232	        }
233	
234	        if (checkChecksum(ctx, checksum)) {
235	          break;
236	        }
237	      }
238	    }
239	  }
240	
241	  if (statusCode >= 300) {
242	    if (statusCode == 404) {
243	      grp->increaseAndValidateFileNotFoundCount();
244	    }
245	    return skipResponseBody(std::move(httpResponse));
246	  }
247	
248	  if (fe->isUniqueProtocol()) {
249	    // Redirection should be considered here. We need to parse
250	    // original URI to get hostname.
251	    const std::string& uri = getRequest()->getUri();
252	    uri_split_result us;
253	    if (uri_split(&us, uri.c_str()) == 0) {
254	      std::string host = uri::getFieldString(us, USR_HOST, uri.c_str());
255	      fe->removeURIWhoseHostnameIs(host);
256	    }
257	  }
258	
259	  if (!getPieceStorage()) {
260	    ctx->setAcceptMetalink(false);
261	    int64_t totalLength = httpResponse->getEntityLength();
262	    fe->setLength(totalLength);
263	    if (fe->getPath().empty()) {
264	      auto suffixPath = util::createSafePath(httpResponse->determineFilename(
265	          getOption()->getAsBool(PREF_CONTENT_DISPOSITION_DEFAULT_UTF8)));
266	      fe->setPath(util::applyDir(getOption()->get(PREF_DIR), suffixPath));
267	      fe->setSuffixPath(suffixPath);
268	    }
269	    fe->setContentType(httpResponse->getContentType());
270	    grp->preDownloadProcessing();
271	
272	    // update last modified time
273	    updateLastModifiedTime(httpResponse->getLastModifiedTime());
274	
275	    // If both transfer-encoding and total length is specified, we
276	    // should have ignored total length.  In this case, we can not do
277	    // segmented downloading
278	    if (totalLength == 0 || shouldInflateContentEncoding(httpResponse.get())) {
279	      // we ignore content-length when inflate is required
280	      fe->setLength(0);
281	      if (req->getMethod() == Request::METHOD_GET &&
282	          (totalLength != 0 || !httpResponse->getHttpHeader()->defined(
283	                                   HttpHeader::CONTENT_LENGTH))) {
284	        // DownloadContext::knowsTotalLength() == true only when
285	        // server says the size of file is 0 explicitly.
286	        getDownloadContext()->markTotalLengthIsUnknown();
287	      }
288	      return handleOtherEncoding(std::move(httpResponse));
289	    }
290	
291	    return handleDefaultEncoding(std::move(httpResponse));
292	  }
293	
294	  if (!ctx->getHashType().empty() && httpHeader->defined(HttpHeader::DIGEST)) {
295	    std::vector<Checksum> checksums;
296	    httpResponse->getDigest(checksums);
297	    for (const auto& checksum : checksums) {
298	      if (checkChecksum(ctx, checksum)) {
299	        break;
300	      }
301	    }
302	  }
303	
304	  // validate totalsize
305	  grp->validateTotalLength(fe->getLength(), httpResponse->getEntityLength());
306	  // update last modified time
307	  updateLastModifiedTime(httpResponse->getLastModifiedTime());
308	
309	  if (grp->getTotalLength() == 0) {
310	    // Since total length is unknown, the file size in previously
311	    // failed download could be larger than the size this time.
312	    // Also we can't resume in this case too.  So truncate the file
313	    // anyway.
314	    getPieceStorage()->getDiskAdaptor()->truncate(0);
315	    auto teFilter = getTransferEncodingStreamFilter(
316	        httpResponse.get(), getContentEncodingStreamFilter(httpResponse.get()));
317	    getDownloadEngine()->addCommand(createHttpDownloadCommand(
318	        std::move(httpResponse), std::move(teFilter)));
319	  }
320	  else {
321	    auto teFilter = getTransferEncodingStreamFilter(httpResponse.get());
322	    getDownloadEngine()->addCommand(createHttpDownloadCommand(
323	        std::move(httpResponse), std::move(teFilter)));
324	  }
325	
326	  return true;
327	}
