336	bool HttpResponseCommand::shouldInflateContentEncoding(
337	    HttpResponse* httpResponse)
338	{
339	  // Basically, on the fly inflation cannot be made with segment
340	  // download, because in each segment we don't know where the date
341	  // should be written.  So turn off segmented downloading.
342	  // Meanwhile, Some server returns content-encoding: gzip for .tgz
343	  // files.  I think those files should not be inflated by clients,
344	  // because it is the original format of those files. Current
345	  // implementation just inflates these files nonetheless.
346	  const std::string& ce = httpResponse->getContentEncoding();
347	  return httpResponse->getHttpRequest()->acceptGZip() &&
348	         (ce == "gzip" || ce == "deflate");
349	}
350	
351	bool HttpResponseCommand::handleDefaultEncoding(
352	    std::unique_ptr<HttpResponse> httpResponse)
353	{
354	  auto progressInfoFile = std::make_shared<DefaultBtProgressInfoFile>(
355	      getDownloadContext(), std::shared_ptr<PieceStorage>{}, getOption().get());
356	  getRequestGroup()->adjustFilename(progressInfoFile);
357	  getRequestGroup()->initPieceStorage();
358	
359	  if (getOption()->getAsBool(PREF_DRY_RUN)) {
360	    onDryRunFileFound();
361	    return true;
362	  }
363	
364	  auto checkEntry = getRequestGroup()->createCheckIntegrityEntry();
365	  if (!checkEntry) {
366	    return true;
367	  }
368	
369	  File file(getRequestGroup()->getFirstFilePath());
370	  // We have to make sure that command that has Request object must
371	  // have segment after PieceStorage is initialized. See
372	  // AbstractCommand::execute()
373	  auto segment = getSegmentMan()->getSegmentWithIndex(getCuid(), 0);
374	  // pipelining requires implicit range specified. But the request for
375	  // this response most likely doesn't contains range header. This means
376	  // we can't continue to use this socket because server sends all entity
377	  // body instead of a segment.
378	  // Therefore, we shutdown the socket here if pipelining is enabled.
379	  if (getRequest()->getMethod() == Request::METHOD_GET && segment &&
380	      segment->getPositionToWrite() == 0 &&
381	      !getRequest()->isPipeliningEnabled()) {
382	    auto teFilter = getTransferEncodingStreamFilter(httpResponse.get());
383	    checkEntry->pushNextCommand(createHttpDownloadCommand(
384	        std::move(httpResponse), std::move(teFilter)));
385	  }
386	  else {
387	    getSegmentMan()->cancelSegment(getCuid());
388	    getFileEntry()->poolRequest(getRequest());
389	  }
390	
391	  prepareForNextAction(std::move(checkEntry));
392	
393	  if (getRequest()->getMethod() == Request::METHOD_HEAD) {
394	    poolConnection();
395	    getRequest()->setMethod(Request::METHOD_GET);
396	  }
397	
398	  return true;
399	}
400	
401	bool HttpResponseCommand::handleOtherEncoding(
402	    std::unique_ptr<HttpResponse> httpResponse)
403	{
404	  // We assume that RequestGroup::getTotalLength() == 0 here
405	  if (getOption()->getAsBool(PREF_DRY_RUN)) {
406	    getRequestGroup()->initPieceStorage();
407	    onDryRunFileFound();
408	    return true;
409	  }
410	
411	  if (getRequest()->getMethod() == Request::METHOD_HEAD) {
412	    poolConnection();
413	    getRequest()->setMethod(Request::METHOD_GET);
414	    return prepareForRetry(0);
415	  }
416	
417	  // In this context, knowsTotalLength() is true only when the file is
418	  // really zero-length.
419	
420	  auto streamFilter = getTransferEncodingStreamFilter(
421	      httpResponse.get(), getContentEncodingStreamFilter(httpResponse.get()));
422	  // If chunked transfer-encoding is specified, we have to read end of
423	  // chunk markers(0\r\n\r\n, for example).
424	  bool chunkedUsed = streamFilter && streamFilter->getName() ==
425	                                         ChunkedDecodingStreamFilter::NAME;
426	
427	  // For zero-length file, check existing file comparing its size
428	  if (!chunkedUsed && getDownloadContext()->knowsTotalLength() &&
429	      getRequestGroup()->downloadFinishedByFileLength()) {
430	    getRequestGroup()->initPieceStorage();
431	
432	    // TODO Known issue: if .aria2 file exists, it will not be deleted
433	    // on successful verification, because .aria2 file is not loaded.
434	    // See also FtpNegotiationCommand::onFileSizeDetermined()
435	    if (getDownloadContext()->isChecksumVerificationNeeded()) {
436	      A2_LOG_DEBUG("Zero length file exists. Verify checksum.");
437	      auto entry = make_unique<ChecksumCheckIntegrityEntry>(getRequestGroup());
438	      entry->initValidator();
439	      getPieceStorage()->getDiskAdaptor()->openExistingFile();
440	      getDownloadEngine()->getCheckIntegrityMan()->pushEntry(std::move(entry));
441	    }
442	    else {
443	      getPieceStorage()->markAllPiecesDone();
444	      getDownloadContext()->setChecksumVerified(true);
445	      A2_LOG_NOTICE(fmt(MSG_DOWNLOAD_ALREADY_COMPLETED,
446	                        GroupId::toHex(getRequestGroup()->getGID()).c_str(),
447	                        getRequestGroup()->getFirstFilePath().c_str()));
448	    }
449	    poolConnection();
450	    return true;
451	  }
452	
453	  getRequestGroup()->adjustFilename(std::make_shared<NullProgressInfoFile>());
454	  getRequestGroup()->initPieceStorage();
455	  getPieceStorage()->getDiskAdaptor()->initAndOpenFile();
456	
457	  // Local file size becomes zero when DiskAdaptor::initAndOpenFile()
458	  // is called. So zero-length file is complete if chunked encoding is
459	  // not used.
460	  if (!chunkedUsed && getDownloadContext()->knowsTotalLength()) {
461	    A2_LOG_DEBUG("File length becomes zero and it means download completed.");
462	    // TODO Known issue: if .aria2 file exists, it will not be deleted
463	    // on successful verification, because .aria2 file is not loaded.
464	    // See also FtpNegotiationCommand::onFileSizeDetermined()
465	    if (getDownloadContext()->isChecksumVerificationNeeded()) {
466	      A2_LOG_DEBUG("Verify checksum for zero-length file");
467	      auto entry = make_unique<ChecksumCheckIntegrityEntry>(getRequestGroup());
468	      entry->initValidator();
469	      getDownloadEngine()->getCheckIntegrityMan()->pushEntry(std::move(entry));
470	    }
471	    else {
472	      getRequestGroup()->getPieceStorage()->markAllPiecesDone();
473	    }
474	    poolConnection();
475	    return true;
476	  }
477	
478	  // We have to make sure that command that has Request object must
479	  // have segment after PieceStorage is initialized. See
480	  // AbstractCommand::execute()
481	  getSegmentMan()->getSegmentWithIndex(getCuid(), 0);
482	
483	  getDownloadEngine()->addCommand(createHttpDownloadCommand(
484	      std::move(httpResponse), std::move(streamFilter)));
485	  return true;
486	}
487	
488	bool HttpResponseCommand::skipResponseBody(
489	    std::unique_ptr<HttpResponse> httpResponse)
490	{
491	  auto filter = getTransferEncodingStreamFilter(httpResponse.get());
492	  // We don't use Content-Encoding here because this response body is just
493	  // thrown away.
494	  auto httpResponsePtr = httpResponse.get();
495	  auto command = make_unique<HttpSkipResponseCommand>(
496	      getCuid(), getRequest(), getFileEntry(), getRequestGroup(),
497	      httpConnection_, std::move(httpResponse), getDownloadEngine(),
498	      getSocket());
499	  command->installStreamFilter(std::move(filter));
500	
501	  // If request method is HEAD or the response body is zero-length,
502	  // set command's status to real time so that avoid read check blocking
503	  if (getRequest()->getMethod() == Request::METHOD_HEAD ||
504	      (httpResponsePtr->getEntityLength() == 0 &&
505	       !httpResponsePtr->isTransferEncodingSpecified())) {
506	    command->setStatusRealtime();
507	    // If entity length == 0, then socket read/write check must be disabled.
508	    command->disableSocketCheck();
509	    getDownloadEngine()->setNoWait(true);
510	  }
511	
512	  getDownloadEngine()->addCommand(std::move(command));
513	  return true;
514	}
