576	bool HttpResponseCommand::checkChecksum(
577	    const std::shared_ptr<DownloadContext>& dctx, const Checksum& checksum)
578	{
579	  if (dctx->getHashType() == checksum.getHashType()) {
580	    if (dctx->getDigest() != checksum.getDigest()) {
581	      throw DL_ABORT_EX("Invalid hash found in Digest header field.");
582	    }
583	    A2_LOG_INFO("Valid hash found in Digest header field.");
584	    return true;
585	  }
586	
587	  return false;
588	}
